solution:
function capitalizeKeys(obj) {
  const result = {};
  for (const key in obj) {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
    const newKey = key.charAt(0).toUpperCase() + key.slice(1);
    result[newKey] = obj[key];
  }
  return result;
}
